#include "tasks.h"

/* ---- door ---- */
static emb_task_event_t door_event;
EMB_MSGQ_DEFINE(door_task_queue, sizeof(emb_task_event_t), 8u, 0u);
static const uint32_t door_timeouts[3] = {0u, 2000u, 0u};

static emb_state_t door_dispatch(emb_state_t state, uint8_t why)
{
    emb_state_t next;
    if (why == EMB_TASK_WHY_TIMEOUT) {
        door_event.id = EMB_EV_TIMEOUT;
        door_event.value = 0u;
    }
    switch (state) {
    case DOOR_CLOSED:
        next = door_on_closed(&door, &door_event);
        break;
    case DOOR_OPEN:
        next = door_on_open(&door, &door_event);
        break;
    case DOOR_JAMMED:
        next = door_on_jammed(&door, &door_event);
        break;
    default:
        next = state;
        break;
    }
    return next;
}

static void door_enter(emb_state_t state)
{
    switch (state) {
    case DOOR_OPEN:
        door_enter_open(&door);
        break;
    default:
        break;
    }
}

static void door_exit(emb_state_t state)
{
    switch (state) {
    case DOOR_OPEN:
        door_exit_open(&door);
        break;
    default:
        break;
    }
}

static const emb_task_desc_t door_desc = {"door", door_dispatch, door_enter, door_exit, &door_event, &door_task_queue,
                                       door_timeouts, 0u, (uint16_t)sizeof(emb_task_event_t), DOOR_CLOSED,
                                       DOOR_STATE_COUNT, EMB_TASK_EVENT, 0u};
door_t door = {.task = {.desc = &door_desc, .state = DOOR_CLOSED}};

static void door_main(void *arg)
{
    (void)arg;
    emb_task_run(&door.task);
}

EMB_THREAD_DEFINE(door_thread, door_main, NULL, 5u, 1024u, 0u);

/* ---- blink ---- */

static emb_state_t blink_dispatch(emb_state_t state, uint8_t why)
{
    emb_state_t next;
    (void)why;
    switch (state) {
    case BLINK_DARK:
        next = blink_on_dark(&blink);
        break;
    case BLINK_LIT:
        next = blink_on_lit(&blink);
        break;
    default:
        next = state;
        break;
    }
    return next;
}

static const emb_task_desc_t blink_desc = {"blink", blink_dispatch, NULL, NULL, NULL, NULL,
                                       NULL, 500u, 0u, BLINK_DARK,
                                       BLINK_STATE_COUNT, EMB_TASK_PERIODIC, 0u};
blink_t blink = {.task = {.desc = &blink_desc, .state = BLINK_DARK}};

static void blink_main(void *arg)
{
    (void)arg;
    emb_task_run(&blink.task);
}

EMB_THREAD_DEFINE(blink_thread, blink_main, NULL, 2u, 512u, 0u);
